import java.util.Arrays;

public class Main {
    static long calls;

    // Step 1: plain recursion. Correct, but exponential.
    static long fibRec(int n) {
        calls++;
        if (n <= 1) return n;
        return fibRec(n - 1) + fibRec(n - 2);
    }

    // Step 2: the same recursion plus a memo table (top-down DP).
    static long fibMemo(int n, long[] memo) {
        calls++;
        if (n <= 1) return n;
        if (memo[n] != -1) return memo[n];
        return memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
    }

    // Step 3: tabulation (bottom-up DP): fill the table from the base cases upward.
    static long fibTab(int n) {
        if (n <= 1) return n;
        long[] dp = new long[n + 1];
        dp[1] = 1;
        for (int i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
        return dp[n];
    }

    // Step 4: space optimisation: dp[i] only needs the previous two values.
    static long fibO1(int n) {
        long prev = 0, cur = 1;
        for (int i = 2; i <= n; i++) {
            long next = prev + cur;
            prev = cur;
            cur = next;
        }
        return n == 0 ? 0 : cur;
    }

    public static void main(String[] args) {
        int n = 35;
        calls = 0;
        long a = fibRec(n);
        System.out.println("recursion  fib(" + n + ") = " + a + "  calls = " + calls);

        long[] memo = new long[n + 1];
        Arrays.fill(memo, -1);
        calls = 0;
        long b = fibMemo(n, memo);
        System.out.println("memo       fib(" + n + ") = " + b + "  calls = " + calls);

        System.out.println("tabulation fib(" + n + ") = " + fibTab(n));
        System.out.println("O(1) space fib(" + n + ") = " + fibO1(n));
        System.out.println("fib(90) = " + fibO1(90) + "  (fits in long; fib(93) overflows)");
    }
}

import java.util.Arrays;

public class Main {
    // dp[i] = best loot using houses 0..i, never robbing two neighbours.
    static int robTable(int[] nums, boolean trace) {
        int n = nums.length;
        if (n == 1) return nums[0];
        int[] dp = new int[n];
        dp[0] = nums[0];
        dp[1] = Math.max(nums[0], nums[1]);
        if (trace) {
            System.out.println("i=0 skip=- take=- dp[0]=" + dp[0]);
            System.out.println("i=1 skip=" + nums[0] + " take=" + nums[1] + " dp[1]=" + dp[1]);
        }
        for (int i = 2; i < n; i++) {
            int skip = dp[i - 1];
            int take = dp[i - 2] + nums[i];
            dp[i] = Math.max(skip, take);
            if (trace) {
                System.out.println("i=" + i + " skip=" + skip + " take=" + take
                    + " dp[" + i + "]=" + dp[i]);
            }
        }
        return dp[n - 1];
    }

    // Same recurrence, two variables instead of an array.
    static int robO1(int[] nums) {
        int prev2 = 0, prev1 = 0;      // best up to i-2 and up to i-1
        for (int x : nums) {
            int cur = Math.max(prev1, prev2 + x);
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }

    // House Robber II: the street is a circle, so house 0 and house n-1 are neighbours.
    static int robCircle(int[] nums) {
        int n = nums.length;
        if (n == 1) return nums[0];
        int a = robO1(Arrays.copyOfRange(nums, 0, n - 1));   // houses 0..n-2
        int b = robO1(Arrays.copyOfRange(nums, 1, n));       // houses 1..n-1
        return Math.max(a, b);
    }

    public static void main(String[] args) {
        int[] nums = {2, 7, 9, 3, 1};
        System.out.println("nums = " + Arrays.toString(nums));
        System.out.println("answer (table) = " + robTable(nums, true));
        System.out.println("answer (O(1) space) = " + robO1(nums));
        System.out.println("circle [2,3,2] = " + robCircle(new int[]{2, 3, 2}));
        System.out.println("circle [1,2,3,1] = " + robCircle(new int[]{1, 2, 3, 1}));
    }
}

public class Main {
    // Climbing stairs: ways(n) = ways(n-1) + ways(n-2).
    static int climb(int n) {
        int a = 1, b = 1;                 // ways(0), ways(1)
        for (int i = 2; i <= n; i++) {
            int c = a + b;
            a = b;
            b = c;
        }
        return b;
    }

    // Min cost climbing stairs: cost[i] is paid when you leave step i; you may start at 0 or 1.
    static int minCost(int[] cost) {
        int n = cost.length;
        int a = 0, b = 0;                 // best cost to stand on step i-2 and i-1
        for (int i = 2; i <= n; i++) {
            int c = Math.min(b + cost[i - 1], a + cost[i - 2]);
            a = b;
            b = c;
        }
        return b;                         // standing "on top", one past the last step
    }

    // Decode ways: dp[i] = number of ways to decode the first i characters of s.
    static int decode(String s, boolean trace) {
        int n = s.length();
        int[] dp = new int[n + 1];
        dp[0] = 1;                        // empty prefix: one way (decode nothing)
        dp[1] = s.charAt(0) == '0' ? 0 : 1;
        if (trace) System.out.println("i=1 one='" + s.charAt(0) + "' dp[1]=" + dp[1]);
        for (int i = 2; i <= n; i++) {
            int one = s.charAt(i - 1) - '0';                    // last digit alone
            int two = (s.charAt(i - 2) - '0') * 10 + one;       // last two digits
            if (one >= 1) dp[i] += dp[i - 1];
            if (two >= 10 && two <= 26) dp[i] += dp[i - 2];
            if (trace) {
                System.out.println("i=" + i + " one=" + one + " two=" + two
                    + " dp[" + i + "]=" + dp[i]);
            }
        }
        return dp[n];
    }

    public static void main(String[] args) {
        System.out.println("climb(5) = " + climb(5));
        System.out.println("minCost([10,15,20]) = " + minCost(new int[]{10, 15, 20}));
        System.out.println("minCost([1,100,1,1,1,100,1,1,100,1]) = "
            + minCost(new int[]{1, 100, 1, 1, 1, 100, 1, 1, 100, 1}));
        System.out.println("decode(\"226\") = " + decode("226", true));
        System.out.println("decode(\"06\") = " + decode("06", false));
        System.out.println("decode(\"1201234\") = " + decode("1201234", false));
    }
}

