import java.util.Arrays;

public class Main {
    // dp[r][c] = cheapest cost of a path from (0,0) to (r,c), moving only right or down.
    static int minPathSum(int[][] g, boolean show) {
        int rows = g.length, cols = g[0].length;
        int[][] dp = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (r == 0 && c == 0) dp[r][c] = g[r][c];
                else if (r == 0) dp[r][c] = dp[r][c - 1] + g[r][c];
                else if (c == 0) dp[r][c] = dp[r - 1][c] + g[r][c];
                else dp[r][c] = Math.min(dp[r - 1][c], dp[r][c - 1]) + g[r][c];
                if (show) {
                    System.out.println("(" + r + "," + c + ") cell=" + g[r][c]
                        + " -> dp=" + dp[r][c]);
                }
            }
        }
        return dp[rows - 1][cols - 1];
    }

    // One row is enough: row[c] holds dp of the row above until we overwrite it.
    static int minPathSum1D(int[][] g) {
        int cols = g[0].length;
        int[] row = new int[cols];
        Arrays.fill(row, Integer.MAX_VALUE);
        row[0] = 0;
        for (int[] line : g) {
            row[0] += line[0];
            for (int c = 1; c < cols; c++) row[c] = Math.min(row[c], row[c - 1]) + line[c];
        }
        return row[cols - 1];
    }

    // Unique paths with obstacles (1 = blocked). Counting paths adds instead of taking min.
    static int uniquePathsObstacles(int[][] g) {
        int cols = g[0].length;
        int[] ways = new int[cols];
        ways[0] = 1;
        for (int[] line : g) {
            for (int c = 0; c < cols; c++) {
                if (line[c] == 1) ways[c] = 0;
                else if (c > 0) ways[c] += ways[c - 1];
            }
        }
        return ways[cols - 1];
    }

    public static void main(String[] args) {
        int[][] grid = {{1, 3, 1}, {1, 5, 1}, {4, 2, 1}};
        System.out.println("grid = " + Arrays.deepToString(grid));
        System.out.println("minPathSum = " + minPathSum(grid, true));
        System.out.println("minPathSum (1 row) = " + minPathSum1D(grid));
        int[][] blocked = {{0, 0, 0}, {0, 1, 0}, {0, 0, 0}};
        System.out.println("unique paths with obstacle = " + uniquePathsObstacles(blocked));
        System.out.println("unique paths 3x7 no obstacle = "
            + uniquePathsObstacles(new int[3][7]));
    }
}

import java.util.Arrays;
import java.util.List;

public class Main {
    // Maximal square of '1's. dp[r][c] = side of the biggest square with BOTTOM-RIGHT corner (r,c).
    static int maximalSquare(char[][] m) {
        int rows = m.length, cols = m[0].length, best = 0;
        int[][] dp = new int[rows + 1][cols + 1];          // padding row/column of zeros
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (m[r - 1][c - 1] == '1') {
                    dp[r][c] = 1 + Math.min(dp[r - 1][c - 1], Math.min(dp[r - 1][c], dp[r][c - 1]));
                    best = Math.max(best, dp[r][c]);
                }
            }
        }
        return best * best;                                  // area, not side
    }

    // Triangle: bottom-up, reusing one array. dp[j] = best sum from here down to the last row.
    static int triangle(List<List<Integer>> t) {
        int n = t.size();
        int[] dp = new int[n];
        for (int j = 0; j < n; j++) dp[j] = t.get(n - 1).get(j);
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j <= i; j++) dp[j] = t.get(i).get(j) + Math.min(dp[j], dp[j + 1]);
        }
        return dp[0];
    }

    // Dungeon game: walk from top-left to bottom-right, health must stay >= 1 at all times.
    // Work BACKWARDS: need[r][c] = minimum health required when ENTERING cell (r,c).
    static int dungeon(int[][] d) {
        int rows = d.length, cols = d[0].length;
        int[][] need = new int[rows + 1][cols + 1];
        for (int[] row : need) Arrays.fill(row, Integer.MAX_VALUE);
        need[rows][cols - 1] = 1;                            // virtual cell below the princess
        need[rows - 1][cols] = 1;
        for (int r = rows - 1; r >= 0; r--) {
            for (int c = cols - 1; c >= 0; c--) {
                int best = Math.min(need[r + 1][c], need[r][c + 1]);
                need[r][c] = Math.max(1, best - d[r][c]);
            }
        }
        return need[0][0];
    }

    public static void main(String[] args) {
        char[][] m = {
            "10100".toCharArray(), "10111".toCharArray(),
            "11111".toCharArray(), "10010".toCharArray()};
        System.out.println("maximalSquare area = " + maximalSquare(m));
        List<List<Integer>> t = List.of(
            List.of(2), List.of(3, 4), List.of(6, 5, 7), List.of(4, 1, 8, 3));
        System.out.println("triangle min path = " + triangle(t));
        int[][] d = {{-2, -3, 3}, {-5, -10, 1}, {10, 30, -5}};
        System.out.println("dungeon min starting health = " + dungeon(d));
    }
}

import java.util.Arrays;

public class Main {
    // Coin change (unbounded): fewest coins that sum to amount, or -1.
    // dp[a] = fewest coins for amount a. INF marks "unreachable".
    static int coinChange(int[] coins, int amount, boolean trace) {
        int INF = amount + 1;                       // larger than any real answer
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++) {
            for (int coin : coins) {
                if (coin <= a && dp[a - coin] + 1 < dp[a]) dp[a] = dp[a - coin] + 1;
            }
            if (trace) System.out.println("a=" + a + " dp=" + dp[a]);
        }
        return dp[amount] >= INF ? -1 : dp[amount];
    }

    public static void main(String[] args) {
        int[] coins = {1, 2, 5};
        System.out.println("coins = " + Arrays.toString(coins) + ", amount = 11");
        System.out.println("answer = " + coinChange(coins, 11, true));
        System.out.println("coins [2], amount 3 -> " + coinChange(new int[]{2}, 3, false));
        System.out.println("greedy trap: coins [1,3,4], amount 6 -> "
            + coinChange(new int[]{1, 3, 4}, 6, false) + " (greedy 4+1+1 would use 3)");
    }
}

import java.util.Arrays;
import java.util.List;

public class Main {
    // 0/1 subset sum: can some subset (each item used at most once) add up to target?
    // Iterate the sum DOWNWARDS so an item cannot be reused within the same pass.
    static boolean subsetSum(int[] nums, int target) {
        boolean[] can = new boolean[target + 1];
        can[0] = true;
        for (int x : nums) {
            for (int s = target; s >= x; s--) can[s] |= can[s - x];
        }
        return can[target];
    }

    // Partition equal subset sum = subset sum with target = total / 2.
    static boolean canPartition(int[] nums) {
        int total = Arrays.stream(nums).sum();
        return total % 2 == 0 && subsetSum(nums, total / 2);
    }

    // Target sum (+/- signs): P - N = target and P + N = total, so P = (total + target) / 2.
    static int targetSum(int[] nums, int target) {
        int total = Arrays.stream(nums).sum();
        if (Math.abs(target) > total || (total + target) % 2 != 0) return 0;
        int want = (total + target) / 2;
        int[] ways = new int[want + 1];
        ways[0] = 1;
        for (int x : nums) {
            for (int s = want; s >= x; s--) ways[s] += ways[s - x];
        }
        return ways[want];
    }

    // Coin change II: number of COMBINATIONS. Coins in the OUTER loop => order does not matter.
    static int combinations(int[] coins, int amount) {
        int[] ways = new int[amount + 1];
        ways[0] = 1;
        for (int coin : coins) {
            for (int a = coin; a <= amount; a++) ways[a] += ways[a - coin];
        }
        return ways[amount];
    }

    // Same loops swapped: amount in the OUTER loop counts ORDERED sequences (permutations).
    static int permutations(int[] coins, int amount) {
        int[] ways = new int[amount + 1];
        ways[0] = 1;
        for (int a = 1; a <= amount; a++) {
            for (int coin : coins) if (coin <= a) ways[a] += ways[a - coin];
        }
        return ways[amount];
    }

    // Word break: dp[i] = true if s[0..i) can be split into dictionary words.
    static boolean wordBreak(String s, List<String> dict) {
        boolean[] dp = new boolean[s.length() + 1];
        dp[0] = true;
        for (int i = 1; i <= s.length(); i++) {
            for (String w : dict) {
                int start = i - w.length();
                if (start >= 0 && dp[start] && s.startsWith(w, start)) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[s.length()];
    }

    public static void main(String[] args) {
        int[] sample = {3, 34, 4, 12, 5, 2};
        System.out.println("subsetSum [3,34,4,12,5,2], 9 = " + subsetSum(sample, 9));
        System.out.println("canPartition [1,5,11,5] = " + canPartition(new int[]{1, 5, 11, 5}));
        System.out.println("canPartition [1,2,3,5] = " + canPartition(new int[]{1, 2, 3, 5}));
        System.out.println("targetSum [1,1,1,1,1], 3 = " + targetSum(new int[]{1, 1, 1, 1, 1}, 3));
        int[] coins = {1, 2, 5};
        System.out.println("combinations amount 5 = " + combinations(coins, 5));
        System.out.println("permutations amount 5 = " + permutations(coins, 5));
        System.out.println("wordBreak leetcode = "
            + wordBreak("leetcode", List.of("leet", "code")));
        System.out.println("wordBreak catsandog = "
            + wordBreak("catsandog", List.of("cats", "dog", "sand", "and", "cat")));
    }
}

public class Main {
    // dp[i][j] = length of the LCS of a[0..i) and b[0..j).
    static int[][] lcsTable(String a, String b) {
        int[][] dp = new int[a.length() + 1][b.length() + 1];
        for (int i = 1; i <= a.length(); i++) {
            for (int j = 1; j <= b.length(); j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1] + 1;
                else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        return dp;
    }

    // Walk back from the corner to recover one actual LCS string.
    static String lcsString(String a, String b, int[][] dp) {
        StringBuilder sb = new StringBuilder();
        int i = a.length(), j = b.length();
        while (i > 0 && j > 0) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {
                sb.append(a.charAt(i - 1));
                i--;
                j--;
            } else if (dp[i - 1][j] >= dp[i][j - 1]) i--;
            else j--;
        }
        return sb.reverse().toString();
    }

    // Edit distance: dp[i][j] = fewest insert/delete/replace ops to turn a[0..i) into b[0..j).
    static int[][] editTable(String a, String b) {
        int[][] dp = new int[a.length() + 1][b.length() + 1];
        for (int i = 0; i <= a.length(); i++) dp[i][0] = i;     // delete i characters
        for (int j = 0; j <= b.length(); j++) dp[0][j] = j;     // insert j characters
        for (int i = 1; i <= a.length(); i++) {
            for (int j = 1; j <= b.length(); j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1];
                else dp[i][j] = 1 + Math.min(dp[i - 1][j - 1],            // replace
                                     Math.min(dp[i - 1][j], dp[i][j - 1])); // delete, insert
            }
        }
        return dp;
    }


    public static void main(String[] args) {
        String a = "abcde", b = "ace";
        int[][] t = lcsTable(a, b);
        System.out.println("LCS of " + a + " and " + b
            + " (rows: _" + a + ", columns: _" + b + ")");
        for (int[] row : t) System.out.println(java.util.Arrays.toString(row));
        System.out.println("length = " + t[a.length()][b.length()]
            + ", one LCS = " + lcsString(a, b, t));

        String x = "horse", y = "ros";
        int[][] e = editTable(x, y);
        System.out.println("edit distance " + x + " -> " + y
            + " (rows: _" + x + ", columns: _" + y + ")");
        for (int[] row : e) System.out.println(java.util.Arrays.toString(row));
        System.out.println("answer = " + e[x.length()][y.length()]);
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class Main {
    // LIS in O(n log n): tails.get(k) = smallest possible last value of an increasing
    // subsequence of length k+1. The list stays sorted, so binary search finds the slot.
    static int lis(int[] nums, boolean trace) {
        List<Integer> tails = new ArrayList<>();
        for (int x : nums) {
            int pos = Collections.binarySearch(tails, x);
            if (pos < 0) pos = -pos - 1;               // insertion point: first tail >= x
            if (pos == tails.size()) tails.add(x);     // x extends the longest subsequence
            else tails.set(pos, x);                    // x is a better (smaller) ending
            if (trace) System.out.println("x=" + x + " pos=" + pos + " tails=" + tails);
        }
        return tails.size();
    }

    // Longest palindromic subsequence: dp[i][j] for the substring s[i..j].
    static int lps(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(i) == s.charAt(j)) dp[i][j] = dp[i + 1][j - 1] + 2;
                else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
        return dp[0][n - 1];
    }

    // Distinct subsequences: ways[j] = number of ways s so far contains t[0..j) as a subsequence.
    static long distinct(String s, String t) {
        long[] ways = new long[t.length() + 1];
        ways[0] = 1;
        for (char ch : s.toCharArray()) {
            for (int j = t.length(); j >= 1; j--) {      // downwards: each char of s used once
                if (t.charAt(j - 1) == ch) ways[j] += ways[j - 1];
            }
        }
        return ways[t.length()];
    }

    // Wildcard matching: '?' = any one char, '*' = any sequence (including empty).
    static boolean wildcard(String s, String p) {
        boolean[][] dp = new boolean[s.length() + 1][p.length() + 1];
        dp[0][0] = true;
        for (int j = 1; j <= p.length(); j++) dp[0][j] = dp[0][j - 1] && p.charAt(j - 1) == '*';
        for (int i = 1; i <= s.length(); i++) {
            for (int j = 1; j <= p.length(); j++) {
                char pc = p.charAt(j - 1);
                if (pc == '*') dp[i][j] = dp[i][j - 1] || dp[i - 1][j];  // empty / eat one char
                else dp[i][j] = dp[i - 1][j - 1] && (pc == '?' || pc == s.charAt(i - 1));
            }
        }
        return dp[s.length()][p.length()];
    }

    public static void main(String[] args) {
        int[] nums = {10, 9, 2, 5, 3, 7, 101, 18};
        System.out.println("nums = " + Arrays.toString(nums));
        System.out.println("LIS length = " + lis(nums, true));
        System.out.println("LPS(\"bbbab\") = " + lps("bbbab"));
        System.out.println("distinct(\"rabbbit\", \"rabbit\") = " + distinct("rabbbit", "rabbit"));
        System.out.println("wildcard(\"adceb\", \"*a*b\") = " + wildcard("adceb", "*a*b"));
        System.out.println("wildcard(\"acdcb\", \"a*c?b\") = " + wildcard("acdcb", "a*c?b"));
    }
}

import java.util.Arrays;

public class Main {
    // Burst balloons. Pad the array with 1 at both ends. dp[l][r] = best coins from bursting
    // every balloon STRICTLY between l and r. Trick: pick k as the LAST balloon to burst
    // in (l, r); then its neighbours at that moment are exactly l and r.
    static int maxCoins(int[] nums, boolean trace) {
        int n = nums.length;
        int[] a = new int[n + 2];
        a[0] = a[n + 1] = 1;
        System.arraycopy(nums, 0, a, 1, n);
        int[][] dp = new int[n + 2][n + 2];
        for (int len = 2; len <= n + 1; len++) {             // distance r - l
            for (int l = 0; l + len <= n + 1; l++) {
                int r = l + len;
                int best = 0, bestK = -1;
                for (int k = l + 1; k < r; k++) {
                    int coins = dp[l][k] + a[l] * a[k] * a[r] + dp[k][r];
                    if (coins > best) {
                        best = coins;
                        bestK = k;
                    }
                }
                dp[l][r] = best;
                if (trace) {
                    System.out.println("len=" + len + " (l=" + l + ",r=" + r + ") last=a[" + bestK
                        + "]=" + a[bestK] + " dp=" + best);
                }
            }
        }
        return dp[0][n + 1];
    }

    // Stock with cooldown: three states per day, each a max profit so far.
    static int stockCooldown(int[] p, boolean trace) {
        int hold = -p[0];      // currently own a share
        int sold = 0;          // sold today (tomorrow must rest)
        int rest = 0;          // own nothing and free to buy
        for (int i = 1; i < p.length; i++) {
            int newHold = Math.max(hold, rest - p[i]);
            int newSold = hold + p[i];
            int newRest = Math.max(rest, sold);
            hold = newHold;
            sold = newSold;
            rest = newRest;
            if (trace) System.out.println("day " + i + " price=" + p[i] + " hold=" + hold
                + " sold=" + sold + " rest=" + rest);
        }
        return Math.max(sold, rest);
    }

    // Stock with at most k transactions. buy[j] / sell[j] = best profit in the j-th transaction.
    static int stockK(int k, int[] p) {
        int[] buy = new int[k + 1];
        int[] sell = new int[k + 1];
        Arrays.fill(buy, Integer.MIN_VALUE / 2);
        for (int price : p) {
            for (int j = 1; j <= k; j++) {
                buy[j] = Math.max(buy[j], sell[j - 1] - price);
                sell[j] = Math.max(sell[j], buy[j] + price);
            }
        }
        return sell[k];
    }

    public static void main(String[] args) {
        int[] balloons = {3, 1, 5, 8};
        System.out.println("balloons = " + Arrays.toString(balloons));
        System.out.println("max coins = " + maxCoins(balloons, true));
        int[] prices = {1, 2, 3, 0, 2};
        System.out.println("prices = " + Arrays.toString(prices));
        System.out.println("cooldown profit = " + stockCooldown(prices, true));
        int[] p2 = {3, 3, 5, 0, 0, 3, 1, 4};
        System.out.println("k=2 on [3,3,5,0,0,3,1,4] = " + stockK(2, p2));
        System.out.println("k=1 on [7,1,5,3,6,4] = " + stockK(1, new int[]{7, 1, 5, 3, 6, 4}));
    }
}

import java.util.Arrays;

public class Main {
    record Node(int val, Node left, Node right) {}

    // House Robber III: each node returns {best if we skip it, best if we rob it}.
    static int[] robTree(Node node) {
        if (node == null) return new int[]{0, 0};
        int[] left = robTree(node.left());
        int[] right = robTree(node.right());
        int skip = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
        int rob = node.val() + left[0] + right[0];     // robbing me forces children to be skipped
        return new int[]{skip, rob};
    }

    // Bitmask DP: shortest tour visiting every city exactly once (Travelling Salesman, n <= ~20).
    // dp[mask][last] = cheapest cost to have visited the cities in mask, standing at `last`.
    static int tsp(int[][] dist) {
        int n = dist.length, full = (1 << n) - 1, INF = 1_000_000_000;
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, INF);
        dp[1][0] = 0;                                   // start at city 0, only city 0 visited
        for (int mask = 1; mask <= full; mask++) {
            for (int last = 0; last < n; last++) {
                if (dp[mask][last] == INF || (mask & (1 << last)) == 0) continue;
                for (int next = 0; next < n; next++) {
                    if ((mask & (1 << next)) != 0) continue;       // already visited
                    int nm = mask | (1 << next);
                    dp[nm][next] = Math.min(dp[nm][next], dp[mask][last] + dist[last][next]);
                }
            }
        }
        int best = INF;
        for (int last = 1; last < n; last++) best = Math.min(best, dp[full][last] + dist[last][0]);
        return best;
    }

    // Can I Win: players alternately pick an unused number 1..max; first to reach total wins.
    static boolean canIWin(int max, int total) {
        if (max * (max + 1) / 2 < total) return false;
        if (total <= 0) return true;
        Boolean[] memo = new Boolean[1 << max];           // memo[usedMask] = does the mover win?
        return win(max, total, 0, memo);
    }

    static boolean win(int max, int remaining, int used, Boolean[] memo) {
        if (memo[used] != null) return memo[used];
        for (int i = 1; i <= max; i++) {
            int bit = 1 << (i - 1);
            if ((used & bit) != 0) continue;
            if (i >= remaining || !win(max, remaining - i, used | bit, memo)) {
                return memo[used] = true;
            }
        }
        return memo[used] = false;
    }

    public static void main(String[] args) {
        Node root = new Node(3, new Node(2, null, new Node(3, null, null)),
                                new Node(3, null, new Node(1, null, null)));
        int[] r = robTree(root);
        System.out.println("robTree: skip root=" + r[0] + ", rob root=" + r[1]
            + " -> best " + Math.max(r[0], r[1]));
        int[][] dist = {{0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
        System.out.println("tsp = " + tsp(dist));
        System.out.println("canIWin(10, 11) = " + canIWin(10, 11));
        System.out.println("canIWin(10, 0)  = " + canIWin(10, 0));
        System.out.println("canIWin(4, 6)   = " + canIWin(4, 6));
    }
}

