import java.util.Arrays;

public class Main {
    // Jump Game: can we reach the last index? Track the farthest index reachable so far.
    static boolean canJump(int[] nums) {
        int farthest = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > farthest) return false;                // stranded: i is unreachable
            farthest = Math.max(farthest, i + nums[i]);
        }
        return true;
    }

    // Jump Game II: fewest jumps. Think in BFS levels: all indices reachable with j jumps
    // form a window [.., end]. The next window ends at the farthest point seen inside this one.
    static int minJumps(int[] nums, boolean trace) {
        int jumps = 0, end = 0, farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            boolean jump = (i == end);
            if (jump) {
                jumps++;
                end = farthest;
            }
            if (trace) {
                System.out.println("i=" + i + " nums[i]=" + nums[i] + " farthest=" + farthest
                    + " end=" + end + " jumps=" + jumps + (jump ? "  <- jump" : ""));
            }
        }
        return jumps;
    }

    // Gas station: if total gas >= total cost a start exists; restart after any negative tank.
    static int gasStation(int[] gas, int[] cost) {
        int total = 0, tank = 0, start = 0;
        for (int i = 0; i < gas.length; i++) {
            int diff = gas[i] - cost[i];
            total += diff;
            tank += diff;
            if (tank < 0) {              // cannot reach i+1 from start; nothing in between works
                start = i + 1;
                tank = 0;
            }
        }
        return total >= 0 ? start : -1;
    }

    // Interval scheduling: the most non-overlapping intervals. Sort by END time, take greedily.
    static int maxNonOverlapping(int[][] iv) {
        Arrays.sort(iv, (x, y) -> Integer.compare(x[1], y[1]));   // not x[1] - y[1]: can overflow
        int count = 0, lastEnd = Integer.MIN_VALUE;
        for (int[] cur : iv) {
            if (cur[0] >= lastEnd) {
                count++;
                lastEnd = cur[1];
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] jumps = {2, 3, 1, 1, 4};
        System.out.println("nums = " + Arrays.toString(jumps));
        System.out.println("minJumps = " + minJumps(jumps, true));
        System.out.println("canJump [3,2,1,0,4] = " + canJump(new int[]{3, 2, 1, 0, 4}));
        System.out.println("canJump [2,3,1,1,4] = " + canJump(jumps));
        int[] gas = {1, 2, 3, 4, 5}, cost = {3, 4, 5, 1, 2};
        System.out.println("gasStation = " + gasStation(gas, cost));
        System.out.println("gasStation impossible = "
            + gasStation(new int[]{2, 3, 4}, new int[]{3, 4, 3}));
        int[][] iv = {{1, 3}, {2, 4}, {3, 5}, {0, 6}, {5, 7}, {8, 9}, {5, 9}};
        int kept = maxNonOverlapping(iv);
        System.out.println("intervals kept = " + kept + ", removed = " + (iv.length - kept));
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

public class Main {
    // Assign cookies: sort both, give each child the smallest cookie that satisfies it.
    static int assignCookies(int[] greed, int[] size) {
        Arrays.sort(greed);
        Arrays.sort(size);
        int child = 0;
        for (int cookie = 0; cookie < size.length && child < greed.length; cookie++) {
        if (size[cookie] >= greed[child]) child++;
    }
    return child;
}

// Candy: two passes. Left-to-right fixes "higher than left neighbour", right-to-left the other.
static int candy(int[] rating) {
    int n = rating.length;
    int[] c = new int[n];
    Arrays.fill(c, 1);
    for (int i = 1; i < n; i++) if (rating[i] > rating[i - 1]) c[i] = c[i - 1] + 1;
    for (int i = n - 2; i >= 0; i--) {
        if (rating[i] > rating[i + 1]) c[i] = Math.max(c[i], c[i + 1] + 1);
    }
    return Arrays.stream(c).sum();
}

// Reorganize string: no two equal neighbours. Always place the most frequent letter that
// is not the one we just placed (a max-heap of counts).
static String reorganize(String s) {
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) freq[ch - 'a']++;
    PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> y[1] - x[1]);   // max-heap by count
    for (int i = 0; i < 26; i++) if (freq[i] > 0) pq.add(new int[]{i, freq[i]});
    StringBuilder sb = new StringBuilder();
    int[] held = null;                                  // letter we must skip for one turn
    while (!pq.isEmpty() || held != null) {
        if (pq.isEmpty()) return "";                    // only the held letter is left
        int[] top = pq.poll();
        sb.append((char) ('a' + top[0]));
        top[1]--;
        if (held != null) pq.add(held);
        held = top[1] > 0 ? top : null;
    }
    return sb.toString();
}

// Partition labels: cut as early as possible so each letter lives in exactly one piece.
static List<Integer> partitionLabels(String s) {
    int[] last = new int[26];
    for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;
    List<Integer> sizes = new ArrayList<>();
    int start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
        end = Math.max(end, last[s.charAt(i) - 'a']);
        if (i == end) {
            sizes.add(end - start + 1);
            start = i + 1;
        }
    }
    return sizes;
}

// Greedy that FAILS: coin change with {1, 3, 4}. Take the biggest coin first.
static int greedyCoins(int[] coins, int amount) {
    int[] sorted = coins.clone();
    Arrays.sort(sorted);
    int count = 0;
    for (int i = sorted.length - 1; i >= 0; i--) {
        count += amount / sorted[i];
        amount %= sorted[i];
    }
    return amount == 0 ? count : -1;
}

public static void main(String[] args) {
    System.out.println("cookies = " + assignCookies(new int[]{1, 2, 3}, new int[]{1, 1}));
    System.out.println("candy [1,0,2] = " + candy(new int[]{1, 0, 2}));
    System.out.println("candy [1,2,2] = " + candy(new int[]{1, 2, 2}));
    System.out.println("reorganize aab = " + reorganize("aab"));
    System.out.println("reorganize aaab = '" + reorganize("aaab") + "'");
    System.out.println("reorganize vvvlo = " + reorganize("vvvlo"));
    System.out.println("labels = " + partitionLabels("ababcbacadefegdehijhklij"));
        System.out.println("greedy coins {1,3,4} for 6 = " + greedyCoins(new int[]{1, 3, 4}, 6)
            + " (optimal is 2: 3+3)");
    }
}

public class Main {
    static String bin(int x, int width) {
        String s = Integer.toBinaryString(x);
        return "0".repeat(Math.max(0, width - s.length())) + s;
    }

    // Brian Kernighan: n & (n - 1) clears the lowest set bit, so the loop runs once per 1-bit.
    static int popcount(int n, boolean trace) {
        int count = 0;
        while (n != 0) {
            int next = n & (n - 1);
            if (trace) {
                System.out.println("n=" + bin(n, 6) + "  n-1=" + bin(n - 1, 6)
                    + "  n&(n-1)=" + bin(next, 6));
            }
            n = next;
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println("popcount(44) via Kernighan:");
        System.out.println("count = " + popcount(44, true));

        int a = 0b1100, b = 0b1010;
        System.out.println("a=" + bin(a, 4) + " b=" + bin(b, 4));
        System.out.println("a & b = " + bin(a & b, 4) + ", a | b = " + bin(a | b, 4)
            + ", a ^ b = " + bin(a ^ b, 4) + ", ~a & 15 = " + bin(~a & 15, 4));
        int n = 0b101100;
        System.out.println("check bit 2: " + ((n >> 2) & 1) + ", set bit 0: " + bin(n | 1, 6));
        System.out.println("clear bit 3: " + bin(n & ~(1 << 3), 6)
            + ", toggle bit 5: " + bin(n ^ (1 << 5), 6));
        System.out.println("lowest set bit of 44: " + (44 & -44)
            + "  (-44 = " + Integer.toBinaryString(-44) + ")");
        System.out.println("isPowerOfTwo: 16 -> " + isPow2(16) + ", 18 -> " + isPow2(18)
            + ", 0 -> " + isPow2(0) + ", MIN_VALUE -> " + isPow2(Integer.MIN_VALUE));
        System.out.println("-8 >> 1 = " + (-8 >> 1) + ", -8 >>> 1 = " + (-8 >>> 1));
        System.out.println("1 << 31 = " + (1 << 31) + ", 1 << 32 = " + (1 << 32)
            + ", 1L << 32 = " + (1L << 32));
        System.out.println("Integer.bitCount(44) = " + Integer.bitCount(44)
            + ", Integer.reverse(1) = " + Integer.reverse(1));
    }

    static boolean isPow2(int n) {
        return n > 0 && (n & (n - 1)) == 0;           // the n > 0 check matters: 0 and MIN_VALUE
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    // Single number: every value appears twice except one. x ^ x = 0 and x ^ 0 = x.
    static int singleNumber(int[] nums) {
        int acc = 0;
        for (int x : nums) acc ^= x;
        return acc;
    }

    // Single Number III: two values appear once. XOR of everything = u ^ v. Any set bit of
    // that XOR separates u from v, so split the array by that bit and XOR each half.
    static int[] singleNumberIII(int[] nums) {
        int xor = 0;
        for (int x : nums) xor ^= x;
        int lowBit = xor & -xor;
        int u = 0, v = 0;
        for (int x : nums) {
            if ((x & lowBit) == 0) u ^= x;
            else v ^= x;
        }
        return new int[]{u, v};
    }

    // Counting bits: bits[i] = bits[i / 2] + (i & 1). Shifting right drops the last bit.
    static int[] countBits(int n) {
        int[] bits = new int[n + 1];
        for (int i = 1; i <= n; i++) bits[i] = bits[i >> 1] + (i & 1);
        return bits;
    }

    // Missing number in 0..n: XOR all indices and all values; pairs cancel, the gap remains.
    static int missingNumber(int[] nums) {
        int acc = nums.length;
        for (int i = 0; i < nums.length; i++) acc ^= i ^ nums[i];
        return acc;
    }

    // Reverse the 32 bits of an int: shift the answer left, feed it the lowest bit of n.
    static int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (n & 1);
            n >>>= 1;                                   // unsigned shift, or the sign bit smears
        }
        return result;
    }

    // All subsets: each mask from 0 to 2^n - 1 is one subset; bit i says "take nums[i]".
    static List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> all = new ArrayList<>();
        for (int mask = 0; mask < (1 << nums.length); mask++) {
            List<Integer> pick = new ArrayList<>();
            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) pick.add(nums[i]);
            }
            all.add(pick);
        }
        return all;
    }

    // Add without +: XOR is the sum ignoring carries, (a & b) << 1 is the carries.
    static int add(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1;
            a ^= b;
            b = carry;
        }
        return a;
    }

    public static void main(String[] args) {
        System.out.println("singleNumber [4,1,2,1,2] = " + singleNumber(new int[]{4, 1, 2, 1, 2}));
        System.out.println("singleNumberIII [1,2,1,3,2,5] = "
            + Arrays.toString(singleNumberIII(new int[]{1, 2, 1, 3, 2, 5})));
        System.out.println("countBits(8) = " + Arrays.toString(countBits(8)));
        System.out.println("missingNumber [3,0,1] = " + missingNumber(new int[]{3, 0, 1}));
        System.out.println("reverseBits(43261596) = " + reverseBits(43261596)
            + " (expected 964176192)");
        System.out.println("subsets [1,2,3] = " + subsets(new int[]{1, 2, 3}));
        System.out.println("add(5, 7) = " + add(5, 7) + ", add(-3, 5) = " + add(-3, 5));
    }
}
